    15	export interface Reminder {
    16	  /** 푸시 태그로도 쓰는 업무 키 — 같은 알림은 늘 같은 키 */
    17	  key: string;
    18	  kind: ReminderKind;
    19	  memberId: string;
    20	  autopayId: string;
    21	  device: string;
    22	  /** 이 알림이 안내하는 출금(또는 재출금) 시각 */
    23	  dueAt: LocalDateTime;
    24	  /** 실제 발송 예약 시각 */
    25	  sendAt: LocalDateTime;
    26	  /** 리포트 묶음 기준일(= 출금일) */
    27	  planDate: LocalDate;
    28	  message: string;
    29	  ticket?: string;
    30	}
    31	
    32	// 재출금 안내도 출금 예정 알림처럼 계약·날짜 단위 키다(1.9.0부터).
    33	// TODO: 하루 두 번째 재출금 안내까지 막히는데 아직 날짜 단위여야 하나?
    34	export function reminderKey(kind: ReminderKind, autopayId: string, dueAt: LocalDateTime): string {
    35	  return `rmd.${autopayId}.${KIND_CODE[kind]}.${dueAt.slice(0, 10).replace(/-/g, "")}`;
    36	}
