     1	import { KIND_LABEL } from "../domain/reminder";
     2	import { maskDevice } from "../push/deviceToken";
     3	import { DeliveredPush, PushqClient } from "../push/pushqClient";
     4	import { ReminderRepository } from "../repository/reminderRepository";
     5	import { compare, LocalDate, LocalDateTime } from "../time/localTime";
     6	
     7	export type LineStatus = "발송" | "미발송" | "예약";
     8	
     9	export interface ReportLine {
    10	  key: string;
    11	  memberId: string;
    12	  kind: string;
    13	  dueAt: LocalDateTime;
    14	  sendAt: LocalDateTime;
    15	  ticket: string;
    16	  device: string;
    17	  status: LineStatus;
    18	  deliveredAt?: LocalDateTime;
    19	}
    20	
    21	export interface ReminderReport {
    22	  date: LocalDate;
    23	  asOf: LocalDateTime | null;
    24	  planned: number;
    25	  delivered: number;
    26	  missing: number;
    27	  pending: number;
    28	  lines: ReportLine[];
    29	  text: string;
    30	}
    31	
    32	/** 출금일 기준 알림 발송 현황 — 운영 화면용 */
    33	export class ReminderReportBuilder {
    34	  constructor(private readonly reminders: ReminderRepository, private readonly push: PushqClient) {}
    35	
    36	  build(date: LocalDate, asOf: LocalDateTime | undefined): ReminderReport {
    37	    const byTag = new Map<string, DeliveredPush>();
    38	    for (const d of this.push.delivered()) if (!byTag.has(d.tag)) byTag.set(d.tag, d);
    39	
    40	    const lines: ReportLine[] = this.reminders.byPlanDate(date).map((r) => {
    41	      const hit = byTag.get(r.key);
    42	      let status: LineStatus;
    43	      if (hit) status = "발송";
    44	      else if (asOf && compare(r.sendAt, asOf) <= 0) status = "미발송";
    45	      else status = "예약";
    46	      return {
    47	        key: r.key,
    48	        memberId: r.memberId,
    49	        kind: KIND_LABEL[r.kind],
    50	        dueAt: r.dueAt,
    51	        sendAt: r.sendAt,
    52	        ticket: r.ticket ?? "-",
    53	        device: maskDevice(r.device),
    54	        status,
    55	        deliveredAt: hit?.at,
    56	      };
    57	    });
    58	    const count = (s: LineStatus) => lines.filter((l) => l.status === s).length;
    59	    const planned = lines.length;
    60	    const delivered = count("발송");
    61	    const missing = count("미발송");
    62	    const pending = count("예약");
    63	    return {
    64	      date,
    65	      asOf: asOf ?? null,
    66	      planned,
    67	      delivered,
    68	      missing,
    69	      pending,
    70	      lines,
    71	      text: `${date} 알림 — 예약 ${planned} / 발송 ${delivered} / 미발송 ${missing} / 대기 ${pending}`,
    72	    };
    73	  }
    74	}
