     1	type Fn = () => void;
     2	const registered: [string, Fn][] = [];
     3	const cleanups: (() => void)[] = [];
     4	
     5	export function test(name: string, fn: Fn): void {
     6	  registered.push([name, fn]);
     7	}
     8	
     9	export function onCleanup(fn: () => void): void {
    10	  cleanups.push(fn);
    11	}
    12	
    13	export function eq(actual: unknown, expected: unknown, label: string): void {
    14	  const a = JSON.stringify(actual);
    15	  const e = JSON.stringify(expected);
    16	  if (a !== e) throw new Error(`${label}: expected ${e}, got ${a}`);
    17	}
    18	
    19	export function assert(cond: boolean, label: string): void {
    20	  if (!cond) throw new Error(label);
    21	}
    22	
    23	export function run(): void {
    24	  let failed = 0;
    25	  for (const [name, fn] of registered) {
    26	    try {
    27	      fn();
    28	      console.log(`ok   - ${name}`);
    29	    } catch (e) {
    30	      failed++;
    31	      console.log(`FAIL - ${name}: ${e instanceof Error ? e.message : String(e)}`);
    32	    }
    33	  }
    34	  for (const c of cleanups) {
    35	    try {
    36	      c();
    37	    } catch {
    38	      /* ignore */
    39	    }
    40	  }
    41	  console.log(failed === 0 ? "all passed" : `${failed} failed`);
    42	  process.exitCode = failed === 0 ? 0 : 1;
    43	}

