    23	export function validateAutopay(input: unknown): Omit<Autopay, "id" | "active"> {
    24	  const b = (input ?? {}) as Record<string, unknown>;
    25	  if (typeof b.memberId !== "string") throw new Error("memberId required");
    26	  if (typeof b.merchant !== "string" || b.merchant.trim() === "") throw new Error("merchant required");
    27	  if (typeof b.amount !== "number" || !Number.isInteger(b.amount) || b.amount <= 0) throw new Error("amount must be a positive integer (KRW)");
    28	  if (typeof b.billingDay !== "number" || !Number.isInteger(b.billingDay) || b.billingDay < 1 || b.billingDay > 28) {
    29	    throw new Error("billingDay must be 1..28");
    30	  }
    31	  if (typeof b.billingTime !== "string" || !/^([01]\d|2[0-3]):[0-5]\d$/.test(b.billingTime)) throw new Error("billingTime must be HH:MM");
