    33	}
    34	
    35	export function validateFailure(autopayId: string, input: unknown): BillingFailure {
    36	  const b = (input ?? {}) as Record<string, unknown>;
    37	  if (!isLocalDateTime(b.failedAt)) throw new Error("failedAt must be YYYY-MM-DDTHH:MM:SS");
    38	  const reason = typeof b.reason === "string" && b.reason !== "" ? b.reason : "INSUFFICIENT_BALANCE";
