    43	    const out = this.run(["schedule", "--to", device, "--at", at, "--tag", tag, message]);
    44	    const m = /^ticket (T\d+)$/m.exec(out);
    45	    if (!m) throw new PushqError("unparsed-output", 0);
    46	    return m[1];
