export function reminderKey(kind: ReminderKind, autopayId: string, dueAt: LocalDateTime): string {
  return `rmd.${autopayId}.${KIND_CODE[kind]}.${dueAt.slice(0, 10).replace(/-/g, "")}`;
}

input.new_string:
// 재출금 안내도 출금 예정 알림처럼 계약·날짜 단위 키다(1.9.0부터).
// 같은 날 두 번째 이후 재출금(nth ≥ 2)은 키 뒤에 순번을 붙여 따로 예약한다.
export function reminderKey(kind: ReminderKind, autopayId: string, dueAt: LocalDateTime, nth = 1): string {
  const base = `rmd.${autopayId}.${KIND_CODE[kind]}.${dueAt.slice(0, 10).replace(/-/g, "")}`;
  return kind === "RETRY" && nth > 1 ? `${base}.${nth}` : base;
